/// Extract root Solid/Shell from a BRep for passing as argument.
fn root_shape(brep: &topods::BRep, location: u32) -> Shape {
    for (i, ts) in brep.tshapes.iter().enumerate().rev() {
        match &**ts {
            TShape::Solid(_) | TShape::Shell(_) => {
                return Shape::from_parts(ts.clone(), i, location, Orientation::Forward);
            }
            _ => {}
        }
    }
    panic!("no root Solid/Shell in BRep");
}

/// Run PaveFiller stage-by-stage and check against OCCT reference.
fn check_pf_stages(
    a: &topods::BRep, b: &topods::BRep,
    label: &str, stages: &[StageExpect],
) {
    for s in stages {
        let mut filler = PaveFiller::new();
        filler.set_arguments(vec![root_shape(a, 0), root_shape(b, 1)]);
        filler.stop_after = Some(s.stage_name);
        let a_prog = NoopProgress;
        let a_ps = ProgressScope::new(&a_prog, "test", 100);
        filler.perform(&a_ps);

        let ds = filler.ds();

        let n_src = ds.nb_source_shapes;
        let nV = ds.shapes.iter().filter(|si| si.shape_type == ShapeType::Vertex).count();
        let nE = ds.shapes.iter().filter(|si| si.shape_type == ShapeType::Edge).count();
        let nF = ds.shapes.iter().filter(|si| si.shape_type == ShapeType::Face).count();
        let nIC = ds.intersection_curves.len();
        let nNewV = ds.shapes.iter().enumerate()
            .filter(|(i, si)| *i >= n_src && si.shape_type == ShapeType::Vertex).count();
        let nNewE = ds.shapes.iter().enumerate()
            .filter(|(i, si)| *i >= n_src && si.shape_type == ShapeType::Edge).count();
        let nPB = (0..ds.nb_shapes()).filter(|&i| ds.shapes[i].shape_type == ShapeType::Edge && ds.shapes[i].reference >= 0)
            .map(|i| ds.pave_blocks_pool[ds.shapes[i].reference as usize].len()).sum::<usize>();
        let nVV = ds.interf_vv.len();
        let nVE = ds.interf_ve.len();
        let nVF = ds.interf_vf.len();
        let nEE = ds.interf_ee.len();
        let nEF = ds.interf_ef.len();
        let nFF = ds.interf_ff.len();

        eprintln!("  {}: V={}/{} E={}/{} F={}/{} IC={}/{} nPB={}/{} nNewV={}/{} nNewE={}/{} | VV={}/{} VE={}/{} VF={}/{} EE={}/{} EF={}/{} FF={}/{}",
            s.stage_name, nV, s.nV, nE, s.nE, nF, s.nF, nIC, s.nIC, nPB, s.nPB, nNewV, s.nNewV, nNewE, s.nNewE,
            nVV, s.interf_VV, nVE, s.interf_VE, nVF, s.interf_VF,
            nEE, s.interf_EE, nEF, s.interf_EF, nFF, s.interf_FF);
        assert_eq!(nV, s.nV, "{} [{}] nV", label, s.stage_name);
        assert_eq!(nE, s.nE, "{} [{}] nE", label, s.stage_name);
        assert_eq!(nF, s.nF, "{} [{}] nF", label, s.stage_name);
        assert_eq!(nIC, s.nIC, "{} [{}] nIC", label, s.stage_name);
        assert_eq!(nPB, s.nPB, "{} [{}] nPB", label, s.stage_name);
        assert_eq!(nNewV, s.nNewV, "{} [{}] nNewV", label, s.stage_name);
        assert_eq!(nNewE, s.nNewE, "{} [{}] nNewE", label, s.stage_name);
        assert_eq!(nVV, s.interf_VV, "{} [{}] VV", label, s.stage_name);
        assert_eq!(nVE, s.interf_VE, "{} [{}] VE", label, s.stage_name);
        assert_eq!(nVF, s.interf_VF, "{} [{}] VF", label, s.stage_name);
        assert_eq!(nEE, s.interf_EE, "{} [{}] EE", label, s.stage_name);
        assert_eq!(nEF, s.interf_EF, "{} [{}] EF", label, s.stage_name);
        assert_eq!(nFF, s.interf_FF, "{} [{}] FF", label, s.stage_name);

        // Verify source vertex positions and tolerances (after_Init only)
        if s.stage_name == "after_Init" {
        let mut vi = 0;
        for i in 0..ds.nb_source_shapes {
            if ds.shapes[i].shape_type == ShapeType::Vertex && vi < s.vertices.len() {
                let (ex, ey, ez, et) = s.vertices[vi];
                let pt = ds.vertex_point_by_idx(i);
                let tol = ds.vertex_tolerance_by_idx(i);
                assert!((pt.x - ex).abs() < 1e-6, "{} [{}] vertex {} x: {:.10} != {:.10}", label, s.stage_name, i, pt.x, ex);
                assert!((pt.y - ey).abs() < 1e-6, "{} [{}] vertex {} y: {:.10} != {:.10}", label, s.stage_name, i, pt.y, ey);
                assert!((pt.z - ez).abs() < 1e-6, "{} [{}] vertex {} z: {:.10} != {:.10}", label, s.stage_name, i, pt.z, ez);
                assert!((tol - et).abs() < 1e-12, "{} [{}] vertex {} tol: {:.15} != {:.15}", label, s.stage_name, i, tol, et);
                vi += 1;
            }
        }
        }

        // ── Per-face FaceInfo (pbIn/pbOn/pbSc/alone-vertices/verticesIn/On) ──
        // OCCT: BOPDS_DS::FaceInfo(i) + BOPDS_DS::AloneVertices(i).
        let mut face_info: Vec<(usize, usize, usize, usize, usize, usize, usize)> = Vec::new();
        for i in 0..ds.nb_source_shapes {
            if ds.shapes[i].shape_type != ShapeType::Face { continue; }
            let fi = ds.face_info(i);
            // AloneVertices (OCCT BOPDS_DS::AloneVertices L1028-1057): the
            // endpoints of PaveBlocksIn/Sc form a fence; only VerticesIn/Sc
            // vertices NOT in that fence count as alone.
            let n_av = {
                let mut fence: std::collections::HashSet<usize> = std::collections::HashSet::new();
                for pb_key in fi.pave_blocks_in.iter().chain(fi.pave_blocks_sc.iter()) {
                    if let Some(pb) = ds.pb_from_ptr(*pb_key) {
                        let r = pb.0.read().unwrap();
                        fence.insert(r.pave1.vertex_idx);
                        fence.insert(r.pave2.vertex_idx);
                    }
                }
                let mut alone = 0;
                for v in fi.vertices_in.iter().chain(fi.vertices_sc.iter()) {
                    if fence.insert(*v) { alone += 1; }
                }
                alone
            };
            face_info.push((i, fi.pave_blocks_in.len(), fi.pave_blocks_on.len(), fi.pave_blocks_sc.len(), n_av, fi.vertices_in.len(), fi.vertices_on.len()));
        }
        assert_eq!(face_info, s.face_info.to_vec(), "{} [{}] face_info", label, s.stage_name);

        // ── Per-edge pave block counts ──
        let mut edge_pb: Vec<(usize, usize)> = Vec::new();
        for i in 0..ds.nb_source_shapes {
            if ds.shapes[i].shape_type != ShapeType::Edge { continue; }
            let n = if ds.shapes[i].reference >= 0 { ds.pave_blocks_pool[ds.shapes[i].reference as usize].len() } else { 0 };
            edge_pb.push((i, n));
        }
        assert_eq!(edge_pb, s.edge_pb.to_vec(), "{} [{}] edge_pb", label, s.stage_name);

        // ── Per-pair interferences (sorted; FF extra = curve count) ──
        let mut interf_pairs: Vec<(usize, usize, usize)> = Vec::new();
        for x in &ds.interf_vv { interf_pairs.push((x.v1, x.v2, 0)); }
        for x in &ds.interf_ve { interf_pairs.push((x.vertex, x.edge, 0)); }
        for x in &ds.interf_vf { interf_pairs.push((x.vertex, x.face, 0)); }
        for x in &ds.interf_ee { interf_pairs.push((x.e1, x.e2, 0)); }
        for x in &ds.interf_ef { interf_pairs.push((x.edge, x.face, 0)); }
        for x in &ds.interf_ff { interf_pairs.push((x.f1, x.f2, x.curves.len())); }
        let mut exp_pairs: Vec<(usize, usize, usize)> = s.interf_pairs.to_vec();
        interf_pairs.sort();
        exp_pairs.sort();
        assert_eq!(interf_pairs, exp_pairs, "{} [{}] interf_pairs", label, s.stage_name);
    }
}


